import base64, zlib, os
F = {}
F['supabase/sim/01_seed_100.sql'] = ''
F['supabase/sim/02_link_me.sql'] = ''
F['supabase/sim/03_cleanup.sql'] = ''
F['supabase/sim/04_scorecard.sql'] = ''
F['supabase/sim/05_test_mode_on.sql'] = ''
F['supabase/sim/06_test_mode_off.sql'] = ''
F['scripts/sim/ts-checks.mjs'] = ''
F['scripts/test-all.sh'] = ''
F['scripts/db-test.sh'] = ''
F['functions/_shared/roles.ts'] = ''
F['.github/workflows/v2-checks.yml'] = ''
F['docs/SIMULATION.md'] = ''
for p, d in F.items():
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, 'wb').write(zlib.decompress(base64.b64decode(d)))
    print('wrote', p)
os.chmod('scripts/test-all.sh', 0o755); os.chmod('scripts/db-test.sh', 0o755)
print('Done.')